def dfs_iter(G, s):
    seen, stack, order = set(), [s], []
    while stack:
        u = stack.pop()
        if u in seen: continue
        seen.add(u); order.append(u)
        for v in G[u]:
            if v not in seen:
                stack.append(v)
    return order
